"use strict";(self.webpackChunkdocumentation=self.webpackChunkdocumentation||[]).push([[5245],{62660:e=>{e.exports=JSON.parse('{"version":{"pluginId":"playground","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"playgroundSidebar":[{"type":"link","label":"UNTP Playground","href":"/tests-untp/playground/docs/","docId":"index","unlisted":false},{"type":"link","label":"Identifying UNTP credential links","href":"/tests-untp/playground/docs/identifying-untp-credential-links","docId":"identifying-untp-credential-links","unlisted":false},{"type":"link","label":"Decrypting encrypted credentials","href":"/tests-untp/playground/docs/decrypting-encrypted-credentials","docId":"decrypting-encrypted-credentials","unlisted":false}]},"docs":{"decrypting-encrypted-credentials":{"id":"decrypting-encrypted-credentials","title":"Decrypting encrypted credentials","description":"An encrypted credential added to the Playground (uploaded, fetched by URL, or verified from a link set) becomes a locked card under an Encrypted heading on the Credentials tab. Decryption happens entirely in your browser: the key is used for the one decrypt call, is never stored, logged or sent anywhere, and clearing or refreshing the page discards it along with every card.","sidebar":"playgroundSidebar"},"identifying-untp-credential-links":{"id":"identifying-untp-credential-links","title":"Identifying UNTP credential links","description":"A resolved link set usually carries more than credentials. A real resolver\'s answer for a product identifier can include product information pages, retailer lists, and other resources alongside any UNTP credentials. The Playground lists the credential links on the link set card and reports how many other links it found without listing them, because the Playground\'s job is validating credentials.","sidebar":"playgroundSidebar"},"index":{"id":"index","title":"UNTP Playground","description":"The UNTP Playground validates UNTP artefacts: verifiable credentials, conformity schemes, and identity-resolver link sets. These pages document behaviour specific to the Playground. They are versioned with the Playground itself, independently of the reference implementation documentation.","sidebar":"playgroundSidebar"}}}}')}}]);